def _merge_small_chunks(self, chunks: list[str]) -> list[str]:
        """Merge chunks below the minimum threshold with adjacent chunks."""
        if not chunks:
            return chunks

        merged: list[str] = []
        for chunk in chunks:
            if merged and _estimate_tokens(chunk) < self.min_chunk:
                # Merge with previous chunk
                merged[-1] = merged[-1] + "\n\n" + chunk
            elif merged and _estimate_tokens(merged[-1]) < self.min_chunk:
                # Previous chunk was too small, merge this one into it
                merged[-1] = merged[-1] + "\n\n" + chunk
            else:
                merged.append(chunk)

        return merged

