def _run_cli(self, *args: str) -> dict[str, Any]:
        """Run a cogz CLI command and return parsed JSON output."""
        # --db and --repo are group-level options that must precede the
        # subcommand name (e.g. `cogz --db X --repo Y consolidate`).
        cmd = [sys.executable, "-m", "cogz.cli", "--db", str(self.db_path)]
        if self.repo_path:
            cmd.extend(["--repo", str(self.repo_path)])
        cmd.extend(args)
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
        if result.returncode != 0:
            return {
                "status": "error",
                "error": result.stderr.strip(),
                "returncode": result.returncode,
            }
        stdout = result.stdout.strip()
        try:
            return json.loads(stdout)
        except json.JSONDecodeError:
            # CLI commands like `index` emit progress text before the JSON
            # payload. Extract the last JSON object from the output.
            json_start = stdout.rfind("\n{")
            if json_start != -1:
                candidate = stdout[json_start + 1:]
                try:
                    return json.loads(candidate)
                except json.JSONDecodeError:
                    pass
            return {"status": "ok", "output": stdout}

def mcp_session(requests, timeout=30):
    """Run MCP stdio session with multiple requests."""
    cmd = [sys.executable, "-m", "cogz.cli", "--db", str(TEST_DB), "--repo", str(COGZ_REPO), "mcp-stdio"]
    env = os.environ.copy()
    env["PYTHONPATH"] = str(COGZ_REPO / "src")
    env["COGZ_DB"] = str(TEST_DB)
    env["COGZ_REPO"] = str(COGZ_REPO)
    proc = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                           stderr=subprocess.PIPE, env=env, cwd=str(COGZ_REPO), text=True)
    responses = {}
    for i, (method, params) in enumerate(requests):
        req = {"jsonrpc": "2.0", "id": i, "method": method}
        if params:
            req["params"] = params
        proc.stdin.write(json.dumps(req) + "\n")
        proc.stdin.flush()
        time.sleep(0.5)
    time.sleep(2)
    # Read all available output
    import select
    output_lines = []
    while True:
        ready, _, _ = select.select([proc.stdout], [], [], 1.0)
        if not ready:
            break
        line = proc.stdout.readline()
        if line:
            output_lines.append(line.strip())
    proc.terminate()
    try:
        proc.wait(timeout=5)
    except subprocess.TimeoutExpired:
        proc.kill()
    for line in output_lines:
        try:
            resp = json.loads(line)
            if "id" in resp:
                responses[resp["id"]] = resp
        except json.JSONDecodeError:
            pass
