def _record_migration_batch(self, conn: sqlite3.Connection, name: str) -> None:
        """Record a migration as applied in the schema_migrations table.

        Idempotent — if the migration is already recorded, this is a no-op.
        Future migrations should call this after successful application.
        """
        try:
            conn.execute(
                "INSERT OR IGNORE INTO schema_migrations (name, applied_at) VALUES (?, ?)",
                (name, now_iso()),
            )
            conn.commit()
        except sqlite3.OperationalError as exc:
            logger.debug(f"Failed to record migration {name}: {exc}")
            # Rollback any pending transaction from the failed INSERT
            try:
                conn.rollback()
            except sqlite3.Error:
                pass

