def _tarjan_scc(self, adj: dict[str, list[str]]) -> list[list[str]]:
        """Iterative Tarjan's SCC algorithm.

        Avoids Python's recursion limit (default 1000 frames) by using
        an explicit work stack.
        """
        index_counter = [0]
        stack: list[str] = []
        lowlink: dict[str, int] = {}
        index: dict[str, int] = {}
        on_stack: set[str] = set()
        result: list[list[str]] = []

        for root in adj:
            if root in index:
                continue
            # Work stack: (node, neighbor_index)
            work_stack: list[tuple[str, int]] = [(root, 0)]
            while work_stack:
                v, pi = work_stack[-1]
                if pi == 0:
                    index[v] = index_counter[0]
                    lowlink[v] = index_counter[0]
                    index_counter[0] += 1
                    stack.append(v)
                    on_stack.add(v)

                neighbors = adj.get(v, [])
                if pi < len(neighbors):
                    work_stack[-1] = (v, pi + 1)
                    w = neighbors[pi]
                    if w not in index:
                        work_stack.append((w, 0))
                    if w in index and w in on_stack:
                        lowlink[v] = min(lowlink[v], index[w])
                else:
                    # All neighbors processed
                    if lowlink[v] == index[v]:
                        result.append(self._pop_scc_from_stack(v, stack, on_stack))
                    work_stack.pop()
