def mcp_session(requests):
    """Send multiple JSON-RPC requests in a single MCP session."""
    cmd = [sys.executable, "-m", "cogz.cli", "--db", str(TEST_DB), "--repo", str(COGZ_REPO), "mcp-stdio"]
    env = os.environ.copy()
    env["PYTHONPATH"] = str(COGZ_REPO / "src")
    env["COGZ_DB"] = str(TEST_DB)
    env["COGZ_REPO"] = str(COGZ_REPO)
    proc = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                            text=True, env=env, cwd=str(COGZ_REPO))
    # Build stdin: initialize, initialized notification, then all requests
    lines = [
        json.dumps({"jsonrpc": "2.0", "id": 0, "method": "initialize",
                    "params": {"protocolVersion": "2024-11-05", "capabilities": {}, "clientInfo": {"name": "test", "version": "1.0"}}}),
        json.dumps({"jsonrpc": "2.0", "method": "notifications/initialized"}),
    ]
    for i, (method, params) in enumerate(requests, 1):
        req = {"jsonrpc": "2.0", "id": i, "method": method}
        if params:
            req["params"] = params
        lines.append(json.dumps(req))
    stdin_data = "\n".join(lines) + "\n"
    try:
        stdout, stderr = proc.communicate(input=stdin_data, timeout=30)
        responses = {}
        for line in stdout.strip().split("\n"):
            if line.strip():
                try:
                    r = json.loads(line)
                    if "id" in r:
                        responses[r["id"]] = r
                except json.JSONDecodeError:
                    pass
        return responses
    except subprocess.TimeoutExpired:
        proc.kill()
        proc.communicate()
        return {}

