def _extract_docstring(node) -> str:
    """Extract the docstring from a function or class node.

    Looks for the first statement in the body being a string literal
    (triple-quoted or single-quoted).
    """
    body = node.child_by_field_name("body")
    if not body:
        return ""

    # First child of body should be the first statement
    for child in body.children:
        if child.type in ("comment", "pass_statement"):
            continue
        if child.type != "expression_statement":
            break
        for expr in child.children:
            if expr.type != "string":
                continue
            return _strip_string_quotes(expr.text.decode("utf-8", errors="replace"))
        # If we hit anything else, there's no docstring
        break
    return ""

