from .results import GateResult


def gate_no_errors(errors: Iterable[str]) -> GateResult:
    errors = list(errors)
    return GateResult("no_silent_failures", not errors, value=len(errors), threshold=0)


def gate_scope_contamination(result_scopes: Iterable[dict[str, Any]], expected: dict[str, Any]) -> GateResult:
    contaminated = [scope for scope in result_scopes if any(scope.get(key) != value for key, value in expected.items())]
