def _fallback_extract(self, source: bytes) -> StructureResult:
        functions: list[dict[str, Any]] = []
        for m in re.finditer(rb"^[A-Za-z_][A-Za-z0-9_\s\*]*\b([A-Za-z_][A-Za-z0-9_]*)\s*\([^)]*\)\s*\{", source, re.MULTILINE):
            name = m.group(1).decode("utf-8", errors="replace")
            if name not in ("if", "while", "for", "switch", "return", "sizeof"):
                functions.append({
                    "name": name,
                    "line": source[:m.start()].count(b"\n") + 1,
                    "column": 0,
                    "calls": [],
                })
        imports = [
            m.group(1).decode("utf-8", errors="replace").strip('"<>')
            for m in re.finditer(rb'#include\s+[<"]([^>"]+)[>"]', source, re.MULTILINE)
        ]
        return StructureResult(functions=functions, imports=imports)

