def _get_entity_vector(self, e: dict) -> list[float] | None:
        """Get embedding vector for an entity, falling back to re-embed."""
        eid = e["entity_id"]
        etype_e = e["entity_type"]
        vec = self.storage.get_embedding_vector(etype_e, eid)
        if vec is None:
            text = self.storage.get_entity_text(etype_e, eid)
            if text:
                try:
                    vec, _ = self.embedding.embed(text)
