def _collect_knowledge_files(self, knowledge_dir: Path) -> list[tuple[str, Path, bool]]:
        """Collect knowledge files from authored and auto namespaces.

        Returns a list of (knowledge_type, path, is_auto) tuples.
        Skips the archive directory.
        """
        file_entries: list[tuple[str, Path, bool]] = []
        for subdir in knowledge_dir.iterdir():
            if not subdir.is_dir():
                continue
            if subdir.name == "auto":
                file_entries.extend(self._collect_auto_files(subdir))
            elif subdir.name == "archive":
