            return {"status": "skipped", "reason": "no_memory_baseline"}
        if self.baseline == "recent_window":
            self._recent.append({"agent": agent, "event": event, "payload": payload})
            self._recent = self._recent[-10:]
            return {"status": "captured", "baseline": self.baseline}
        return self.delegate.capture_event(agent, event, payload, **scope)

