def _query_learning_entities(
        self,
        query_fn_name: str,
        text_field: str = "statement",
        limit: int = 10,
        taxonomy: Taxonomy | None = None,
        skip_domain: bool = False,
    ) -> tuple[list[str] | None, dict | None]:
        """Query learning layer entities, return (texts, source_dict) or (None, None).

        When ``skip_domain`` is True, the domain filter is omitted — useful for
        recency-based queries (e.g. cold_start) where observations span many
        domains within the same project/subcategory.
        """
        if self.learning is None:
            return None, None
        query_fn = getattr(self.learning, query_fn_name, None)
        if query_fn is None:
            return None, None
        kwargs: dict[str, Any] = {}
        if taxonomy is not None:
            if taxonomy.project:
                kwargs["project"] = taxonomy.project
            if taxonomy.subcategory:
                kwargs["subcategory"] = taxonomy.subcategory
            if taxonomy.domain and not skip_domain:
                kwargs["domain"] = taxonomy.domain
        entities = sorted(query_fn(**kwargs), key=lambda e: e.get("created_at", ""), reverse=True)
        if not entities:
            return None, None
        texts = [e[text_field] for e in entities[:limit]]
        return texts, {"type": "learning", "query": query_fn_name.removeprefix("query_"), "count": len(entities)}

def load_jsonl(path: Path) -> Iterator[dict[str, Any]]:
    if not path.is_file():
        raise FileNotFoundError(path)
    for line_number, line in enumerate(path.read_text().splitlines(), start=1):
        if not line.strip():
            continue
        try:
            value = json.loads(line)
        except json.JSONDecodeError as exc:
            raise ValueError(f"Invalid JSONL at {path}:{line_number}: {exc}") from exc
        if not isinstance(value, dict):
            raise ValueError(f"Expected object at {path}:{line_number}")
        yield value

