        """Check that supersedes edges point to existing entities.

        Skipped until Phase 2 adds consolidation status columns.
        """
        with self.storage._connect() as conn:
            # Check if any supersedes edges exist
            supersedes = conn.execute(
                "SELECT COUNT(*) FROM edges WHERE type = 'supersedes'"
            ).fetchone()[0]
            if supersedes == 0:
                return CheckResult(
                    "consolidation_lineage",
                    "skipped",
                    {"reason": "No supersedes edges yet (Phase 2+)"},
                )
            # Check for orphaned supersedes edges
            orphaned = conn.execute(
                """SELECT e.id, e.source_id, e.target_id FROM edges e
                   WHERE e.type = 'supersedes'
                   AND (e.source_id NOT IN (SELECT id FROM nodes)
                        OR e.target_id NOT IN (SELECT id FROM nodes))"""
            ).fetchall()
        if not orphaned:
            return CheckResult("consolidation_lineage", "ok", {"supersedes_count": supersedes})
        issues = [
            {
                "edge_id": row[0],
                "issue": "orphaned_supersedes",
                "source_id": row[1],
                "target_id": row[2],
                "severity": "error",
            }
            for row in orphaned
        ]
        return CheckResult("consolidation_lineage", "error", {}, issues, fixable=True)

