def _run_schema_migrations(
        self, conn: sqlite3.Connection,
        migrations: list[str], index_migrations: list[str],
    ) -> None:
        """Run all schema migrations in a single transaction.

        If the process crashes mid-migration, the database won't be left
        in a partially migrated state — either all migrations apply or none.
        After migrations, rebuilds fts_nodes if needed.
        """
        conn.execute("BEGIN")
        try:
            for sql in migrations:
                self._apply_idempotent_migration(
                    conn, sql, "duplicate column name", "Migration failed (non-idempotent)",
                )
            for sql in index_migrations:
                self._apply_idempotent_migration(
                    conn, sql, "already exists", "Index migration failed",
                )
            conn.commit()
        except Exception:
            conn.rollback()
            raise
        # Rebuild fts_nodes if the searchable_text column was just added.
        # FTS5 virtual tables can't be ALTERed — must drop and recreate.
        self._rebuild_fts_nodes_if_needed(conn)

