def check_schema_drift(self) -> CheckResult:
        """Compare actual table columns against expected schema.

        Reports missing columns and unexpected extra columns.
        """
        issues: list[dict[str, Any]] = []
        with self.storage._connect() as conn:
            for table, expected_cols in EXPECTED_COLUMNS.items():
                try:
                    rows = conn.execute(f"PRAGMA table_info({table})").fetchall()
                except Exception as exc:
                    logger.debug(f"Schema drift check: table {table} missing: {exc}")
                    issues.append({
                        "table": table,
                        "issue": "table_missing",
                        "severity": "error",
                    })
                    continue
                actual_cols = {row[1] for row in rows}
                missing = expected_cols - actual_cols
                if missing:
                    issues.append({
                        "table": table,
                        "issue": "missing_columns",
                        "columns": sorted(missing),
                        "severity": "error",
                    })
        if not issues:
            return CheckResult("schema_drift", "ok", {"tables_checked": len(EXPECTED_COLUMNS)})
        return CheckResult(
            "schema_drift",
            "error",
            {"tables_checked": len(EXPECTED_COLUMNS)},
            issues,
            fixable=False,  # Schema changes require migrations, not auto-fix
        )

