def check_knowledge_files(self, knowledge_layer=None) -> CheckResult:
        """Check knowledge file ↔ DB consistency.

        Phase 3.5: Verifies that knowledge files and DB records are in sync.
        Checks for orphaned files, stale files, renamed files, orphaned DB
        records, and overwritten files.

        Args:
            knowledge_layer: Optional KnowledgeLayer instance. If None,
                falls back to the instance passed at construction time.
        """
        if knowledge_layer is None:
            knowledge_layer = self.knowledge
        if knowledge_layer is None or knowledge_layer.repo_path is None:
            return CheckResult(
                "knowledge_files",
                "skipped",
                {"reason": "No KnowledgeLayer or repo_path configured"},
            )

        issues_dict = knowledge_layer.verify_files()
        all_issues: list[dict[str, Any]] = []
        for category, items in issues_dict.items():
            for item in items:
                item["category"] = category
                item["severity"] = "error" if category in ("overwritten_files", "orphaned_db") else "warning"
                all_issues.append(item)

        if not all_issues:
            with self.storage._connect() as conn:
                kb_count = conn.execute("SELECT COUNT(*) FROM knowledge").fetchone()[0]
            return CheckResult("knowledge_files", "ok", {"knowledge_entries": kb_count})
        return CheckResult("knowledge_files", "warning", {}, all_issues, fixable=True)

